/**
 * The Playwright extension's token, in one file of the person's own.
 *
 * WHY IT IS NEEDED AT ALL
 *   Without a token the extension asks the person to approve every connection, in a page opened
 *   in their browser — and cc-smart-dev-kit never runs that way (`browser mcp` refuses to start
 *   without a token). With it, the extension connects on its own.
 *
 * WHERE IT COMES FROM, AND WHERE IT GOES
 *   The token is generated by the extension itself and kept in ITS storage; nothing outside it
 *   can read it (Playwright's own tests read the value off the extension's status page). So the
 *   person copies it and pastes it. The status page shows the line
 *   `PLAYWRIGHT_MCP_EXTENSION_TOKEN=<token>`, and its Copy button copies THE WHOLE LINE — so both
 *   the line and the bare token are accepted here.
 *
 *   It is written to `<config dir>/cc-smart-dev-kit/playwright-extension.token`, mode 0600, and
 *   read back only by the launcher, which puts it in the Playwright MCP child's ENVIRONMENT
 *   (`PLAYWRIGHT_MCP_EXTENSION_TOKEN`). It never reaches a command line (`argv` is world-readable
 *   in `/proc`), never `~/.claude.json`, and is never printed by any command, error or log: the
 *   messages name the file, never the value.
 *
 *   On Windows the mode protects nothing (the numbers are synthetic there) and the profile's ACL
 *   is what keeps the token to its owner: `isOwnerOnly` is why a file there is never refused.
 *
 * THE SHAPE
 *   The extension makes 32 random bytes, base64-encodes them and makes that URL-safe
 *   (`packages/extension/src/ui/authToken.tsx`): 43 characters of `A-Z a-z 0-9 - _`. A token that
 *   is not that shape is refused at paste time — a half-copied token otherwise only shows up
 *   later, as "Invalid token provided." in the browser and a 30-second wait in the session.
 */

import { existsSync, mkdirSync, readFileSync, statSync, unlinkSync } from "node:fs";
import { dirname } from "node:path";
import { COMMAND } from "../build-info";
import type { CliPaths } from "../cli/paths";
import { cleanSecretLine } from "../cli/secret-line";
import { hostPlatform } from "../machine/host";
import { isOwnerOnly } from "../setup/file-mode";
import { atomicWrite } from "../setup/write";

/** The environment variable the Playwright MCP reads the token from. */
export const BROWSER_TOKEN_ENV = "PLAYWRIGHT_MCP_EXTENSION_TOKEN";

/** What the extension's Copy button puts on the clipboard, before the token itself. */
const TOKEN_LINE_PREFIX = `${BROWSER_TOKEN_ENV}=`;

/** The extension's own token: 43 URL-safe base64 characters. */
const TOKEN_SHAPE = /^[A-Za-z0-9_-]{43}$/;

/** How the token file is read: one place, so a test reads its own file. */
export interface TokenDeps {
  exists?: (path: string) => boolean;
  /** The file's mode bits and text, or null when it cannot be read. */
  read?: (file: string) => { mode: number; text: string } | null;
}

export type BrowserToken =
  /** The token file has a usable token. */
  | { source: "file"; value: string }
  /** No usable token: the reason says what to do, and never holds a value. */
  | { source: "none"; reason: string };

/** Does the text hold the extension's token? */
export function isBrowserToken(token: string): boolean {
  return TOKEN_SHAPE.test(token);
}

/**
 * One pasted line as a token: the bracketed-paste markers and every other control character a
 * paste carries are dropped first (`cleanSecretLine` — a terminal that keeps bracketed paste on
 * hands a raw-mode read `ESC[200~<token>ESC[201~`, which this used to refuse), then surrounding
 * whitespace and the `PLAYWRIGHT_MCP_EXTENSION_TOKEN=` prefix the Copy button includes, then the
 * shape is checked. The message a person reads names the shape, the count of characters that were
 * left, and the one place to copy the token from — never a value.
 */
export function parseBrowserToken(
  pasted: string,
): { ok: true; token: string } | { ok: false; why: string } {
  let text = cleanSecretLine(pasted);
  if (text.startsWith(TOKEN_LINE_PREFIX)) text = text.slice(TOKEN_LINE_PREFIX.length).trim();
  if (text === "") {
    return {
      ok: false,
      why: "nothing was pasted. Copy the token from the extension's status page",
    };
  }
  if (!isBrowserToken(text)) {
    return {
      ok: false,
      why:
        `that is not the Playwright extension's token (${String(text.length)} characters; its ` +
        `own token is exactly 43 letters, digits, "-" and "_"). Open the extension's status ` +
        `page and press Copy, then paste the whole line`,
    };
  }
  return { ok: true, token: text };
}

/**
 * The token, from its file. Never prints a value: a refusal names the file and what to do.
 * A missing file is the ordinary case on a machine that has not run `browser token` yet.
 *
 * A file the group or others can read is refused on Linux and macOS, where the mode says so;
 * on Windows the profile's ACL is what protects it, and no file is refused over its bits
 * (`isOwnerOnly`).
 */
export function readBrowserToken(
  paths: CliPaths,
  deps: TokenDeps = {},
  platform: NodeJS.Platform = hostPlatform(),
): BrowserToken {
  const exists = deps.exists ?? existsSync;
  const read =
    deps.read ??
    ((file: string) => {
      try {
        return { mode: statSync(file).mode & 0o7777, text: readFileSync(file, "utf8") };
      } catch {
        return null;
      }
    });
  if (!exists(paths.browserTokenFile)) {
    return {
      source: "none",
      reason: `no token file at ${paths.browserTokenFile}`,
    };
  }
  let file: { mode: number; text: string } | null;
  try {
    file = read(paths.browserTokenFile);
  } catch (error) {
    return {
      source: "none",
      reason: `${paths.browserTokenFile} cannot be read (${error instanceof Error ? error.message : String(error)})`,
    };
  }
  if (file === null) {
    return {
      source: "none",
      reason: `${paths.browserTokenFile} cannot be read; run \`${COMMAND} browser token\` again`,
    };
  }
  if (!isOwnerOnly(file.mode, platform)) {
    return {
      source: "none",
      reason:
        `${paths.browserTokenFile} is readable by others (mode ${file.mode.toString(8)}): ` +
        `run \`chmod 600 ${paths.browserTokenFile}\`, then start a new session`,
    };
  }
  const value = file.text.trim();
  if (value === "") {
    return {
      source: "none",
      reason: `${paths.browserTokenFile} is empty; write the token into it`,
    };
  }
  if (!isBrowserToken(value)) {
    return {
      source: "none",
      reason:
        `${paths.browserTokenFile} does not hold the extension's token: run ` +
        `\`${COMMAND} browser token\` again and paste it from the extension's status page`,
    };
  }
  return { source: "file", value };
}

/**
 * How the token file is kept to its owner, in words: its mode on Linux and macOS; on Windows a
 * mode says nothing, and the user profile's own permissions are what keep it (`isOwnerOnly`).
 */
export function tokenProtection(platform: NodeJS.Platform = hostPlatform()): string {
  return platform === "win32" ? "your user profile's permissions keep it yours" : "mode 600";
}

/** The line `browser token` prints after a save: the command line's and the portal's one wording. */
export function tokenSavedLine(file: string, platform: NodeJS.Platform = hostPlatform()): string {
  return `+ ${file}: the browser token is set (${tokenProtection(platform)})`;
}

/**
 * Writes the token: the file, mode 0600, in a folder only its owner can read. The token is never
 * printed, returned or logged; the caller prints the path.
 */
export function writeBrowserToken(paths: CliPaths, token: string): void {
  mkdirSync(dirname(paths.browserTokenFile), { mode: 0o700, recursive: true });
  atomicWrite(paths.browserTokenFile, `${token}\n`, 0o600);
}

/** Removes the token file. Returns the path when one was there, else null. */
export function clearBrowserToken(paths: CliPaths): null | string {
  if (!existsSync(paths.browserTokenFile)) return null;
  unlinkSync(paths.browserTokenFile);
  return paths.browserTokenFile;
}

/** Where the pasted token is read from: a pipe or a file, or a terminal with no echo. */
export interface TokenInput {
  isTTY: boolean;
  /** Everything on stdin, up to its end (a pipe, or `< token.txt`). */
  readAll: () => Promise<string>;
  /**
   * The question, then a terminal's own line read with no echo and cleaned: the prompts' secret
   * read (`src/cli/ui/prompt.ts`). Left out when the terminal cannot hide what is typed.
   */
  readSecret?: (question: string) => Promise<null | string>;
}

/** What `browser token` asks on a terminal; the secret read adds that the token is not shown. */
export const TOKEN_QUESTION = "Paste the token from the extension's status page, then press Enter";

/**
 * The token a person pasted. On a terminal the line is read with no echo (the token is a secret,
 * and a terminal shows what it receives); from a pipe or a file it is read as it is. Nothing is
 * printed but the one question (`TOKEN_QUESTION`), which says the token is not shown.
 *
 * A terminal whose echo cannot be switched off throws instead of reading: the caller then says to
 * pipe the token in, which never shows it either. (Without that, `readAll` on a terminal would
 * wait for Ctrl+D and echo the token — the one thing this must not do.)
 */
export async function readTokenFromStdin(input: TokenInput): Promise<null | string> {
  if (input.isTTY) {
    if (input.readSecret === undefined) {
      throw new Error(
        "this terminal cannot hide what you type, so the token would be shown on screen",
      );
    }
    return await input.readSecret(TOKEN_QUESTION);
  }
  return await input.readAll();
}

/**
 * Reads a pasted token and saves it — the ONE place the four outcomes of `browser token` are
 * decided, so each of them is testable (the CLI entry just calls this):
 *
 *   - **0, saved**: the token's own file, mode 0600, and the line that says so — never the token.
 *   - **130**: Ctrl+C at the prompt (the read answered null), and nothing was written.
 *   - **1**: a shape that is not the extension's token (the reason names the shape and the
 *     characters that were left), and nothing was written.
 *   - **1**: the read itself FAILED (a broken pipe, a terminal that cannot hide what is typed).
 *     Its own reason is printed with the two ways in (`< token.txt`, or the portal's Browser
 *     card) — never "Nothing was saved (Ctrl+C)", which would be a lie about a read error
 *     (premium review, 2026-10-17).
 */
export async function savePastedToken(
  paths: CliPaths,
  input: TokenInput,
  say: (line: string) => void,
  error: (line: string) => void,
): Promise<number> {
  let pasted: null | string;
  try {
    pasted = await readTokenFromStdin(input);
  } catch (cause) {
    const why = cause instanceof Error ? cause.message : String(cause);
    error(
      `${why}. Save the token to a file and pipe it in (\`${COMMAND} browser token < token.txt\`), or paste it in the portal's Browser card (\`${COMMAND} portal\`).`,
    );
    return 1;
  }
  if (pasted === null) {
    error("Nothing was saved (Ctrl+C).");
    return 130;
  }
  const parsed = parseBrowserToken(pasted);
  if (!parsed.ok) {
    error(`The token was not saved: ${parsed.why}.`);
    return 1;
  }
  writeBrowserToken(paths, parsed.token);
  // The token itself is never printed, only the file it went to.
  say(tokenSavedLine(paths.browserTokenFile));
  say("Start a new Claude session (or restart the running one) to use it.");
  return 0;
}
